            comp = set()
            stack = [(r + dr, c + dc) for dr, dc in
                     ((1, 0), (-1, 0), (0, 1), (0, -1))
                     if 0 <= r + dr < h and 0 <= c + dc < w
                     and grid[r + dr][c + dc] == 1]
            while stack:
