            sizes = [(2, 2), (2, 3)]
        elif color == 8:
            sizes = [(2, 4)]
        elif color == 6:
            sizes = [(2, 2)]
        else:
            sizes = [(1, 2), (2, 2), (2, 3), (3, 3)]

        for bh, bw in sizes:
            for r in range(1, h - bh):
                for c in range(1, w - bw):
                    if not all(grid[y][x] == 1
                               for y in range(r, r + bh)
                               for x in range(c, c + bw)):
