                    if horizontal or vertical:
                        for y in range(r, r + bh):
                            for x in range(c, c + bw):
                                g[y][x] = color

    # Original marker cells stay intact.
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (0, 1):
                g[r][c] = grid[r][c]
